for key, value in {'STATE':c['state'],'CASE':c['id'],'BINDING':c['execution_binding']['binding_id'],'ENVIRONMENT':c['execution_binding']['environment_id'],'PR_URL':c['pr']['url'],'CI_URL':c['ci']['run_url'],'BUILD_URL':c['build']['run_url'],'MERGE_SHA':c['merge']['merge_sha'],'DIGEST':c['build']['image_digest']}.items():
    body = body.replace(key,esc(value))
body = body.replace('SESSION_ROWS',''.join(rows)).replace('WINDOW_ROWS',windows)
a.output.write_text(body)
print(a.output)
